	private static final class RunCursor implements AutoCloseable {

		private final DataInputStream input;
		private final long[] tuple;
		private final Path path;
		private final boolean deleteWhenClosed;
		private boolean present;
		private boolean closed;

		private RunCursor(Path path, int width, BulkCompression compression) throws IOException {
			this(path, width, compression, false);
		}

		private RunCursor(Path path, int width, BulkCompression compression, boolean deleteWhenClosed)
				throws IOException {
			this.path = path;
			this.deleteWhenClosed = deleteWhenClosed;
			input = BulkLz4.input(path, compression);
			tuple = new long[width];
		}

		private boolean advance() throws IOException {
			try {
				tuple[0] = input.readLong();
			} catch (EOFException e) {
				present = false;
				return false;
			}
			try {
				for (int i = 1; i < tuple.length; i++) {
					tuple[i] = input.readLong();
				}
			} catch (EOFException e) {
				throw new IOException("Truncated external tuple run", e);
			}
			present = true;
			return true;
		}

		@Override
		public void close() throws IOException {
			if (closed) {
				return;
			}
			closed = true;
			try {
				input.close();
			} finally {
				if (deleteWhenClosed) {
					Files.deleteIfExists(path);
				}
			}
		}
	}

	/**
	 * Fixed tournament storage with the same allocation behavior as a loser tree: one cursor object per run and no
	 * per-row heap churn.
	 */
	private static final class LoserTree {

		private final RunCursor[] cursors;
		private final int width;
		private final int leafCount;
		private final int[] winners;

		private LoserTree(RunCursor[] cursors, int width) {
			this.cursors = cursors;
			this.width = width;
			int leaves = 1;
			while (leaves < cursors.length) {
				leaves <<= 1;
			}
			leafCount = leaves;
			winners = new int[leafCount << 1];
			Arrays.fill(winners, -1);
			for (int i = 0; i < cursors.length; i++) {
				winners[leafCount + i] = cursors[i].present ? i : -1;
			}
			for (int node = leafCount - 1; node > 0; node--) {
				winners[node] = winner(winners[node << 1], winners[node << 1 | 1]);
			}
		}

		private int winner() {
			return winners[1];
		}

		private void updated(int cursor) {
			int node = leafCount + cursor;
			winners[node] = cursors[cursor].present ? cursor : -1;
			while ((node >>= 1) > 0) {
				winners[node] = winner(winners[node << 1], winners[node << 1 | 1]);
			}
		}

		private int winner(int left, int right) {
			if (left < 0) {
				return right;
			}
			if (right < 0) {
				return left;
			}
			int comparison = compare(cursors[left].tuple, 0, cursors[right].tuple, 0, width);
			return comparison < 0 || comparison == 0 && left < right ? left : right;
		}
	}

	static final class SortedTupleFile {

		private final Path path;
		private final int width;
		private final long rows;
		private final BulkCompression compression;

		private SortedTupleFile(Path path, int width, long rows, BulkCompression compression) {
			this.path = path;
			this.width = width;
			this.rows = rows;
			this.compression = compression;
		}

		static SortedTupleFile restore(Path path, int width, long rows, long bytes, BulkCompression compression)
				throws IOException {
			if (width <= 0 || rows < 0L || bytes < 0L) {
				throw new IOException("Invalid sorted tuple metadata for " + path);
			}
			// The on-disk file is LZ4-compressed, so its size no longer derives from rows*width*8. Validate against
			// the actual byte size recorded when the file was produced.
			if (!Files.isRegularFile(path) || Files.size(path) != bytes) {
				throw new IOException("Sorted tuple file size mismatch for " + path + ": expected "
						+ bytes + " bytes");
			}
			return new SortedTupleFile(path, width, rows, compression);
		}

		Path path() {
			return path;
		}

		long rows() {
			return rows;
		}

		void forEach(TupleConsumer consumer) throws IOException {
			try (RunCursor cursor = new RunCursor(path, width, compression)) {
				while (cursor.advance()) {
					consumer.accept(cursor.tuple);
				}
			}
		}
	}

	@FunctionalInterface
	interface TupleConsumer {
		void accept(long[] tuple) throws IOException;
	}
